import itertools, random, json, subprocess, sys
from fractions import Fraction
sys.path.insert(0,'/workspace/submission')
import analyze

def paths(nodes,edges,src,dst):
 out=[]
 def rec(cur,path,seen):
  if cur==dst:
   if path:out.append(path[:])
   return
  for ei,e in enumerate(edges):
   if e['source']==cur and e['target'] not in seen:
    rec(e['target'],path+[e['id']],seen|{e['target']})
 rec(src,[],{src})
 return out

def brute(x):
 C=x['commodities']; E=x['edges']; S=x['snapshots']; D=x['domains']
 arrays=[[range(lo,hi+1) for lo,hi in s['bounds']] for s in S]
 best=None; models=[]
 for rows in itertools.product(*(itertools.product(*a) for a in arrays)):
  bad=set(); ok=True; all_links=[]; mets=[]
  for si,(s,q) in enumerate(zip(S,rows)):
   links={e['id']:Fraction(0) for e in E}; met={}
   for c,v in zip(C,q):
    met['demand',c['id']]=v
    W=sum(r['weight'] for r in c['routes'])
    for r in c['routes']:
     for ei in r['edges']:links[ei]+=Fraction(v*r['weight'],W)
   for n in x['nodes']:
    met['ingress',n]=sum(v for c,v in zip(C,q) if c['source']==n)
    met['egress',n]=sum(v for c,v in zip(C,q) if c['target']==n)
   met.update({('link',e):v for e,v in links.items()})
   if any(links[e['id']]>e['capacity'] for e in E):ok=False;break
   for o in s['observations']:
    v=met[o['metric'],o['target']]
    if not o['lower']<=v<=o['upper']:
     if o['domain'] is None:ok=False;break
     bad.add(o['domain'])
   if not ok:break
   all_links.append(links);mets.append(met)
  if not ok or len(bad)>x['max_faults']:continue
  if best is None or len(bad)<best:best=len(bad);models=[]
  if len(bad)==best:models.append((rows,all_links,bad))
 if best is None:return {'id':x['id'],'status':'infeasible'}
 forced=set(D);possible=set()
 for _,_,bad in models:forced &= bad;possible |= bad
 unique=len({rows for rows,_,_ in models})==1
 out={'id':x['id'],'status':'unique' if unique else 'ambiguous','min_faults':best,
      'faults':{'forced':[d for d in D if d in forced],'possible':[d for d in D if d in possible]},'snapshots':[]}
 for si,s in enumerate(S):
  qs=[[rows[si][ci] for rows,_,_ in models] for ci in range(len(C))]
  dr=[[min(v),max(v)] for v in qs]
  lr=[]
  for e in E:
   vals=[links[e['id']] for _,links,_ in models]
   lr.append([[str(v.numerator)+'/'+str(v.denominator) for v in (min(vals),max(vals))]][0])
  agrees=[all(abs(rows[si][ci]-v)<=s['tolerance'] for ci,v in enumerate(s['controller'])) for rows,_,_ in models]
  verdict='consistent' if all(agrees) else 'inconsistent' if not any(agrees) else 'undetermined'
  out['snapshots'].append({'id':s['id'],'demands':dr,'links':lr,'verdict':verdict})
 return out

def gen(r):
 n=r.randint(2,4);nodes=[chr(65+i) for i in range(n)]
 edges=[]
 for i in range(n):
  for j in range(n):
   if i!=j and r.random()<.65:
    edges.append({'id':'e%d_%d'%(i,j),'source':nodes[i],'target':nodes[j],'capacity':r.randint(0,8)})
 if not edges:edges=[{'id':'e','source':nodes[0],'target':nodes[1],'capacity':5}]
 commodities=[]
 pairs=list(itertools.permutations(nodes,2));r.shuffle(pairs)
 for ci,(src,dst) in enumerate(pairs[:r.randint(0,min(2,len(pairs)))]):
  ps=paths(nodes,edges,src,dst)
  if not ps:continue
  routes=[]
  for _ in range(r.randint(1,min(3,len(ps)))):
   routes.append({'edges':r.choice(ps),'weight':r.randint(1,4)})
  while sum(z['weight'] for z in routes)>8:routes.pop()
  commodities.append({'id':'c%d'%ci,'source':src,'target':dst,'routes':routes})
 domains=['d%d'%i for i in range(r.randint(0,3))]
 snaps=[]
 for si in range(r.randint(1,2)):
  bounds=[[0,r.randint(0,3)] for c in commodities]
  controller=[r.randint(0,3) for c in commodities]
  obs=[]
  targets=[('demand',c['id']) for c in commodities]+[('link',e['id']) for e in edges]+[(z,n) for n in nodes for z in ('ingress','egress')]
  r.shuffle(targets)
  for oi,(metric,target) in enumerate(targets[:r.randint(0,min(6,len(targets)))]):
   center=r.randint(-1,6);lo=center-r.randint(0,1);hi=center+r.randint(0,1)
   obs.append({'id':'o%d'%oi,'metric':metric,'target':target,'lower':lo,'upper':hi,'domain':r.choice([None]+domains) if domains else None})
  snaps.append({'id':'s%d'%si,'bounds':bounds,'controller':controller,'tolerance':r.randint(0,2),'observations':obs})
 return {'id':'r','version':1,'nodes':nodes,'edges':edges,'commodities':commodities,'domains':domains,'max_faults':r.randint(0,len(domains)),'snapshots':snaps}

r=random.Random(93845)
for it in range(500):
 x=gen(r)
 # regenerate if brute state space is excessive
 size=1
 for s in x['snapshots']:
  for lo,hi in s['bounds']:size*=hi-lo+1
 if size>20000:continue
 a=analyze.analyze_valid(x);b=brute(x)
 for key in ('id','status','min_faults','faults','snapshots'):
  if key in b and a.get(key)!=b[key]:
   print('MISMATCH',it,key,json.dumps(x),json.dumps(a),json.dumps(b),sep='\n');sys.exit(1)
 if b['status']=='infeasible':continue
 # Independently compare every witness against a brute optimal demand matrix.
 # (Brute models recomputed here only in compact instances.)
print('differential random test passed')
